import numpy as np

def problem(x: np.ndarray) -> float:
    x_scaled = x / 5
    term1 = np.sum(np.cos(2 * np.pi * x_scaled))
    term2 = np.sum(x_scaled * np.array([0.1, -0.3, 0.2]))
    peak_location = np.array([0.2, -0.1, 0.3])
    term3 = np.exp(-1 / (1e-6 + np.sum((x_scaled - peak_location)**2)))

    product = np.prod(x_scaled)
    if np.abs(product) < 1e-8:
      term4 =1.0
    else:
      term4 = np.sin(product) / product  # Sinc function

    return float(0.4 * term1 + term2 + 0.2 * term3 + 0.1 * term4)

import numpy as np

def problem(x: np.ndarray) -> float:
    x_scaled = x / 5
    term1 = np.sum(np.cos(2 * np.pi * x_scaled))
    term2 = np.sum(x_scaled * np.array([0.1, -0.3, 0.2]))

    product = np.prod(x_scaled)
    if np.abs(product) < 1e-8:
      term3 =1.0
    else:
      term3 = np.sin(product) / product  # Sinc function

    return float(0.4 * term1 + term2 + 0.1 * term3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x_scaled = x / 5
    term1 = np.sin(2 * np.pi * (x_scaled[0] + x_scaled[1]))
    term2 = np.sum(x_scaled**2) * np.exp(-np.sum((x_scaled - np.array([0.5, -0.5, 0.0]))**2) / 0.5)
    term3 = np.sum(np.abs(x_scaled)**(1/2) * np.array([0.2, -0.1, 0.3]) * np.exp(-5 * np.abs(x_scaled[0])))

    # New non-separable term
    interaction = np.tanh(x_scaled[0] * x_scaled[1] * (x_scaled[2] + 1))
    logarithmic_barrier = 0.0
    for i in range(3):
        if x_scaled[i] >= 1.0:
            logarithmic_barrier += np.log(x_scaled[i]) * 0.01  # Add a small logarithmic term only if x > 1
        else:
            logarithmic_barrier -= x_scaled[i] * 0.1  # And a small logarithmic term if x <= 1
    term4 = interaction + logarithmic_barrier

    return float(0.4 * term1 + 0.3 * term2 + 0.2 * term3 + 0.1 * term4)
